CREATE TABLE IF NOT EXISTS zukan_dispute_cases ( dispute_case_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, resolution_run_id UUID REFERENCES zukan_resolution_runs(resolution_run_id) ON DELETE SET NULL, opened_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), details JSONB NOT NULL DEFAULT '{}'::jsonb, FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE TABLE IF NOT EXISTS zukan_dispute_case_events ( dispute_case_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dispute_case_id UUID NOT NULL REFERENCES zukan_dispute_cases(dispute_case_id) ON DELETE RESTRICT, event_type TEXT NOT NULL, event_payload JSONB NOT NULL DEFAULT '{}'::jsonb, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (event_type IN ('opened', 'under_review', 'resolved', 'dismissed', 'reopened')) ); CREATE TABLE IF NOT EXISTS zukan_correction_requests ( correction_request_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dispute_case_id UUID REFERENCES zukan_dispute_cases(dispute_case_id) ON DELETE SET NULL, subject_id UUID NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, claim_revision_id UUID REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE SET NULL, requested_by_subject_id UUID REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, request_payload JSONB NOT NULL, requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW() ); CREATE TABLE IF NOT EXISTS zukan_correction_request_events ( correction_request_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correction_request_id UUID NOT NULL REFERENCES zukan_correction_requests(correction_request_id) ON DELETE RESTRICT, event_type TEXT NOT NULL, event_payload JSONB NOT NULL DEFAULT '{}'::jsonb, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (event_type IN ('submitted', 'under_review', 'accepted', 'partially_accepted', 'rejected', 'withdrawn')) ); CREATE TABLE IF NOT EXISTS zukan_suppression_requests ( suppression_request_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), target_kind TEXT NOT NULL, target_id UUID NOT NULL, requested_action TEXT NOT NULL, requested_by_subject_id UUID REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, request_reason TEXT NOT NULL, request_payload JSONB NOT NULL DEFAULT '{}'::jsonb, requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (target_kind IN ('content_object', 'value_artifact', 'claim_revision', 'projection_snapshot', 'publication_edition')), CHECK (requested_action IN ('suppress', 'redact', 'erase')), CHECK (length(trim(request_reason)) > 0) ); CREATE TABLE IF NOT EXISTS zukan_suppression_request_events ( suppression_request_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), suppression_request_id UUID NOT NULL REFERENCES zukan_suppression_requests(suppression_request_id) ON DELETE RESTRICT, event_type TEXT NOT NULL, governance_event_id UUID REFERENCES zukan_content_governance_events(governance_event_id) ON DELETE SET NULL, event_payload JSONB NOT NULL DEFAULT '{}'::jsonb, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (event_type IN ('submitted', 'under_review', 'approved', 'rejected', 'executed', 'withdrawn')) ); CREATE TABLE IF NOT EXISTS zukan_survey_events ( survey_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL, workspace_id TEXT, subject_scope JSONB NOT NULL, method JSONB NOT NULL, effort JSONB NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (ended_at IS NULL OR ended_at >= started_at) ); CREATE TABLE IF NOT EXISTS zukan_detection_outcomes ( detection_outcome_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), survey_event_id UUID NOT NULL REFERENCES zukan_survey_events(survey_event_id) ON DELETE RESTRICT, subject_id UUID NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, outcome TEXT NOT NULL, evidence_content_object_id UUID REFERENCES zukan_content_objects(content_object_id) ON DELETE SET NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (outcome IN ('detected', 'not_detected', 'indeterminate')), UNIQUE (survey_event_id, subject_id) ); CREATE TABLE IF NOT EXISTS zukan_coverage_assessments ( coverage_assessment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL, workspace_id TEXT, scope JSONB NOT NULL, predicate_uri TEXT, predicate_version INTEGER, coverage_status TEXT NOT NULL, derived_from JSONB NOT NULL DEFAULT '[]'::jsonb, assessed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (coverage_status IN ('assessed', 'unassessed', 'not_applicable')), CHECK (jsonb_typeof(derived_from) = 'array'), CHECK ((predicate_uri IS NULL AND predicate_version IS NULL) OR (predicate_uri IS NOT NULL AND predicate_version IS NOT NULL)), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_zukan_coverage_assessments_scope ON zukan_coverage_assessments (tenant_id, workspace_id, coverage_status, assessed_at DESC); DROP TRIGGER IF EXISTS trg_zukan_governance_events_no_update ON zukan_content_governance_events; CREATE TRIGGER trg_zukan_governance_events_no_update BEFORE UPDATE OR DELETE ON zukan_content_governance_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_snapshot_status_no_update ON zukan_snapshot_status_events; CREATE TRIGGER trg_zukan_snapshot_status_no_update BEFORE UPDATE OR DELETE ON zukan_snapshot_status_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_publication_availability_no_update ON zukan_publication_availability_events; CREATE TRIGGER trg_zukan_publication_availability_no_update BEFORE UPDATE OR DELETE ON zukan_publication_availability_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_rights_evaluations_no_update ON zukan_rights_evaluations; CREATE TRIGGER trg_zukan_rights_evaluations_no_update BEFORE UPDATE OR DELETE ON zukan_rights_evaluations FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_dispute_cases_no_update ON zukan_dispute_cases; CREATE TRIGGER trg_zukan_dispute_cases_no_update BEFORE UPDATE OR DELETE ON zukan_dispute_cases FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_dispute_case_events_no_update ON zukan_dispute_case_events; CREATE TRIGGER trg_zukan_dispute_case_events_no_update BEFORE UPDATE OR DELETE ON zukan_dispute_case_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_correction_requests_no_update ON zukan_correction_requests; CREATE TRIGGER trg_zukan_correction_requests_no_update BEFORE UPDATE OR DELETE ON zukan_correction_requests FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_correction_request_events_no_update ON zukan_correction_request_events; CREATE TRIGGER trg_zukan_correction_request_events_no_update BEFORE UPDATE OR DELETE ON zukan_correction_request_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_suppression_requests_no_update ON zukan_suppression_requests; CREATE TRIGGER trg_zukan_suppression_requests_no_update BEFORE UPDATE OR DELETE ON zukan_suppression_requests FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_suppression_request_events_no_update ON zukan_suppression_request_events; CREATE TRIGGER trg_zukan_suppression_request_events_no_update BEFORE UPDATE OR DELETE ON zukan_suppression_request_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_detection_outcomes_no_update ON zukan_detection_outcomes; CREATE TRIGGER trg_zukan_detection_outcomes_no_update BEFORE UPDATE OR DELETE ON zukan_detection_outcomes FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_coverage_assessments_no_update ON zukan_coverage_assessments; CREATE TRIGGER trg_zukan_coverage_assessments_no_update BEFORE UPDATE OR DELETE ON zukan_coverage_assessments FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation();
